let mode=new URLSearchParams(location.search).get('category')==='Weaves'?'products':'services',category=new URLSearchParams(location.search).get('category')==='Weaves'?'Weaves':'All';const $=s=>document.querySelector(s),dialog=$('#dialog');const money=n=>'R'+n.toLocaleString('en-ZA');
function render(){const q=$('#search').value.toLowerCase(),loc=$('#location').value;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#heading').textContent=mode==='services'?'A stylist for your style':'Good hair starts with good care';$('#kicker').textContent=mode==='services'?'FIND YOUR NEXT LOOK':'SHOP INDEPENDENT SELLERS';$('#filters').innerHTML=(mode==='services'?['All','Braids']:['All','Wigs','Weaves','Extensions','Haircare','Accessories']).map(c=>`<button class="chip ${c===category?'selected':''}" data-category="${c}" aria-pressed="${c===category}">${c==='All'?'Explore all':c}</button>`).join('');const result=listings.filter(x=>x.kind===mode&&(category==='All'||x.category===category)&&(!loc||x.location===loc)&&`${x.title} ${x.seller} ${x.category}`.toLowerCase().includes(q));$('#count').textContent=`${result.length} listings`;$('#grid').innerHTML=result.length?result.map(x=>`<article class="card"><div class="photo">${x.art?`<div class="art">${x.art}</div>`:`<img src="assets/salon.jpeg" alt="Hairstyles from the Diplomatic Hair Salon reference flyer" style="object-position:${x.position}">`}<span class="badge">${x.category}</span></div><h3>${x.title}</h3><p class="meta">${x.seller}</p><p class="meta">⌖ ${x.location}</p><div class="card-bottom"><strong>${money(x.price)}</strong><button data-id="${x.id}">${mode==='services'?'View & book':'View product'} ↗</button></div></article>`).join(''):'<div class="empty">No matches yet. Try another search or location.</div>';}
function show(html){$('#detail').innerHTML=html;if(!dialog.open)dialog.showModal();const title=$('#detail h2');if(title){title.id='dialog-title';dialog.setAttribute('aria-labelledby','dialog-title')}const focusTarget=$('#detail input, #detail button');if(focusTarget)focusTarget.focus()}
function detail(id){const x=listings.find(x=>x.id===id);if(!x)throw Error('Unknown listing');show(`<p class="eyebrow">${x.category} · SAMPLE LISTING</p><h2>${x.title}</h2><p>${x.seller}<br>${x.location}</p><h3>${money(x.price)}</h3><p>${x.description}</p>${x.kind==='services'?`<form id="booking"><label for="date">Preferred date</label><input type="date" id="date" required min="${new Date().toLocaleDateString('en-CA')}"><label for="time">Preferred time</label><select id="time"><option>09:00</option><option>11:00</option><option>13:00</option><option>15:00</option></select><button class="primary">Preview booking request</button></form>`:'<label for="quantity">Quantity</label><input id="quantity" type="number" min="1" max="10" step="1" required value="1"><button class="primary" id="bag">Preview order</button>'}`);if(x.kind==='services')$('#booking').onsubmit=e=>{e.preventDefault();show(`<h2>Your booking preview</h2><p>${x.title} · ${money(x.price)}<br>${$('#date').value} at ${$('#time').value}</p><p>This is a demo. No appointment has been requested or confirmed.</p><button class="primary" id="done">Continue browsing</button>`);$('#done').onclick=()=>dialog.close()};else $('#bag').onclick=()=>{const n=Number($('#quantity').value);if(!Number.isInteger(n)||n<1||n>10){$('#quantity').reportValidity();return}show(`<h2>Your order preview</h2><p>${n} × ${x.title}<br>Total: <strong>${money(n*x.price)}</strong></p><p>This is a demo. Checkout and delivery are not connected yet. No payment has been taken.</p>`)};return {id:x.id,title:x.title}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mode){mode=b.dataset.mode;category='All';render()}if(b.dataset.category){category=b.dataset.category;render()}if(b.dataset.id)detail(Number(b.dataset.id))});$('#search').oninput=render;$('#location').onchange=render;$('.close').onclick=()=>dialog.close();$('#sell').onclick=()=>{show('<p class="eyebrow">YOUR BUSINESS, YOUR CROWN</p><h2>Create your shop</h2><p>Try your seller profile. This preview stays open only for this session and is not published.</p><form id="seller"><label for="name">Business name</label><input id="name" required maxlength="80"><label for="type">What do you offer?</label><select id="type"><option>Hair services</option><option>Hair products</option><option>Both services and products</option></select><label for="city">Town or city</label><input id="city" required maxlength="80"><button class="primary">Preview my profile</button></form>');$('#seller').onsubmit=e=>{e.preventDefault();const name=$('#name').value,city=$('#city').value;show('<p class="eyebrow">SELLER PROFILE PREVIEW</p><h2 id="seller-name"></h2><p id="seller-city"></p><p>Your shop will bring your products, services and customer reviews together. Registration and publishing will be added in the next development stage.</p>');$('#seller-name').textContent=name;$('#seller-city').textContent=city}};
render();if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_listing',description:'Open a sample marketplace listing without making a booking or purchase.',inputSchema:{type:'object',properties:{id:{type:'integer'}},required:['id'],additionalProperties:false},execute:input=>{if(!Number.isInteger(input.id))throw Error('id must be an integer');return detail(input.id)}})).catch(()=>{})}catch{}}
